(function(root){
 function create({manifest,makeAudio,storage,clock={setTimeout,clearTimeout},onChange=()=>{}}){
  const key='draw-weapon:audio:v1';let enabled=true,volume=.35,unlocked=false,blocked=false,visible=true,current=null,revision=0,duck=1,duckTimer=null;
  const cues=new Set();try{const saved=JSON.parse(storage?.getItem(key)||'null');if(typeof saved?.enabled==='boolean')enabled=saved.enabled;if(Number.isFinite(saved?.volume))volume=Math.max(0,Math.min(1,saved.volume));}catch{}
  function persist(){try{storage?.setItem(key,JSON.stringify({enabled,volume}));}catch{}}
  function applyVolume(){if(current){current.intro&&(current.intro.volume=volume*duck);current.loop.volume=volume*duck;}for(const audio of cues)audio.volume=Math.min(1,volume*1.5);}
  function stopCurrent(){if(current){current.intro?.pause();current.loop.pause();}current=null;}
  function safelyPlay(audio){if(!audio||!enabled||!unlocked||!visible)return;const token=revision;const result=error=>{if(token!==revision)return;blocked=error?.name==='NotAllowedError';onChange();};try{const play=audio.play();play?.then?.(()=>result(),result);}catch(error){result(error);}}
  function resume(){if(!current||!enabled||!visible||!unlocked)return;const audio=current.intro&&!current.introDone?current.intro:current.loop;if(audio.paused)safelyPlay(audio);}
  function setTrack(id){if(current?.id===id){resume();return;}revision++;stopCurrent();const track=manifest.tracks[id];if(!track)return;const token=revision,loop=makeAudio('assets/audio/'+track.loop),intro=track.intro?makeAudio('assets/audio/'+track.intro):null;loop.loop=true;loop.preload='metadata';if(intro){intro.preload='metadata';intro.addEventListener('ended',()=>{if(token!==revision||!current)return;current.introDone=true;resume();});intro.addEventListener('error',()=>{if(token!==revision||!current)return;current.introDone=true;resume();});}current={id,intro,loop,introDone:!intro};applyVolume();resume();}
  function unlock(){unlocked=true;resume();}
  function setEnabled(value){enabled=!!value;persist();if(enabled)resume();else{current?.intro?.pause();current?.loop.pause();for(const cue of cues)cue.pause();}}
  function setVolume(value){if(!Number.isFinite(value))return;volume=Math.max(0,Math.min(1,value));applyVolume();persist();}
  function setVisible(value){visible=value;if(visible)resume();else{current?.intro?.pause();current?.loop.pause();for(const cue of cues)cue.pause();}}
  function cue(name){if(!enabled||!unlocked||!visible||!manifest.cues[name])return;const audio=makeAudio('assets/audio/'+manifest.cues[name]);cues.add(audio);audio.volume=Math.min(1,volume*1.5);const clean=()=>cues.delete(audio);audio.addEventListener('ended',clean,{once:true});audio.addEventListener('error',clean,{once:true});safelyPlay(audio);return audio;}
  function duckFor(ms){duck=.2;applyVolume();clock.clearTimeout(duckTimer);duckTimer=clock.setTimeout(()=>{duck=1;applyVolume();},ms);}
  function stopCues(){for(const cue of cues)cue.pause();cues.clear();clock.clearTimeout(duckTimer);duck=1;applyVolume();}
  function destroy(){revision++;stopCurrent();stopCues();}
  return{setTrack,unlock,setEnabled,setVolume,setVisible,cue,duckFor,stopCues,destroy,read:()=>({enabled,volume,track:current?.id||null,unlocked,blocked})};
 }
 const api={create};if(typeof module!=='undefined'&&module.exports){module.exports=api;return;}
 let storage;try{storage=root.localStorage;}catch{}
 let updateControls=()=>{};const manifest=root.GameAudioManifest,engine=create({manifest,makeAudio:src=>new Audio(src),storage,onChange:()=>updateControls()});let battleState=null,baseScene='title',loading=0;
 const scene=name=>{baseScene=name;engine.setTrack(loading?'loading':name);};
 root.GameAudio={...engine,scene,battle(state){battleState={stage:state.stage,bossPhase:state.bossPhase};scene(manifest.battleTrack(state));},loading(active){loading=Math.max(0,loading+(active?1:-1));engine.setTrack(loading?'loading':baseScene);},evolution(active){engine.stopCues();if(active){engine.duckFor(5000);engine.cue('evolutionRise');}else{engine.duckFor(3200);engine.cue('evolutionComplete');}}};
 function boot(){
  const page=location.pathname.split('/').pop();if(page==='battle.html'){const p=new URLSearchParams(location.hash.slice(1));root.GameAudio.battle(battleState||{stage:Number(p.get('stage'))||0,bossPhase:Number(document.querySelector('.enemy-fighter')?.dataset.phase)||0});}else scene(page==='start.html'?'title':page==='evolve.html'?'loading':'workshop');
  const controls=document.createElement('section');controls.className='game-audio-controls';controls.setAttribute('aria-label','게임 소리');const toggle=document.createElement('button'),label=document.createElement('label'),volume=document.createElement('input'),credits=document.createElement('button'),dialog=document.createElement('dialog'),close=document.createElement('button'),heading=document.createElement('h2');toggle.type=credits.type=close.type='button';
  const update=()=>{const state=engine.read();toggle.textContent=state.enabled?(state.blocked?'소리 켜기':'음악 켜짐'):'음악 꺼짐';toggle.setAttribute('aria-pressed',String(state.enabled));};toggle.addEventListener('click',()=>{const state=engine.read();engine.setEnabled(state.blocked?true:!state.enabled);engine.unlock();update();});updateControls=update;label.append('음량 ');volume.type='range';volume.min=0;volume.max=100;volume.value=engine.read().volume*100;volume.setAttribute('aria-label','음악 음량');volume.addEventListener('input',()=>engine.setVolume(Number(volume.value)/100));label.append(volume);credits.textContent='음원 출처';dialog.className='game-audio-credits';heading.textContent='음악과 효과음';close.textContent='닫기';close.addEventListener('click',()=>dialog.close());dialog.append(heading);
  for(const[title,author,license,slug]of manifest.credits){const p=document.createElement('p'),link=document.createElement('a'),by=document.createElement('span'),terms=document.createElement('a');link.href='https://opengameart.org/content/'+slug;link.target='_blank';link.rel='noopener';link.textContent=title;by.textContent=author+' · ';terms.href=license==='CC0'?'https://creativecommons.org/publicdomain/zero/1.0/':'https://creativecommons.org/licenses/by/3.0/';terms.target='_blank';terms.rel='noopener';terms.textContent=license;p.append(link,document.createElement('br'),by,terms);dialog.append(p);}const note=document.createElement('p');note.textContent='원곡을 사용하며 게임에서 반복 재생합니다. Rise03은 AIFF에서 WAV로 형식만 변환했습니다.';dialog.append(note,close);credits.addEventListener('click',()=>dialog.showModal());controls.append(toggle,label,credits);document.querySelector('main').append(controls);document.body.append(dialog);update();engine.unlock();
 }
 document.addEventListener('pointerdown',event=>{if(!event.target.closest?.('.game-audio-controls'))engine.unlock();},{passive:true});document.addEventListener('keydown',event=>{if(!event.target.closest?.('.game-audio-controls'))engine.unlock();});document.addEventListener('visibilitychange',()=>engine.setVisible(!document.hidden));window.addEventListener('pagehide',()=>engine.destroy());window.addEventListener('game:new-game',()=>engine.destroy());
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})(typeof window!=='undefined'?window:globalThis);
